const entities = [];
let prev = 0;
function frame(now) {                                // before the next repaint
  const dt = Math.min((now - prev) / 1000, 0.25);    // ms -> s, clamped
  prev = now;
  for (const e of entities) e.update(dt);            // one step per object
  requestAnimationFrame(frame);                      // one-shot: re-request
}
requestAnimationFrame(frame);
